const listSgkPremiums = `-- name: ListSgkPremiums :many
SELECT s.id, s.uuid, s.taxpayer_id, s.period, s.payroll_run_id, s.accrual_amount, s.incentive_amount, s.payable_amount, s.due_date, s.document_no, s.paid_amount, s.paid_at, s.bank_transaction_id, s.note, s.created_at, s.updated_at, bt.uuid AS bank_transaction_uuid
FROM sgk_premiums s
LEFT JOIN bank_transactions bt ON bt.id = s.bank_transaction_id AND bt.taxpayer_id = s.taxpayer_id
WHERE s.taxpayer_id = $1
  AND ($2::text IS NULL OR left(s.period, 4) = $2::text)
ORDER BY s.period DESC
LIMIT $4 OFFSET $3
`

type ListSgkPremiumsParams struct {
	TaxpayerID int64       `json:"taxpayer_id"`
	Year       pgtype.Text `json:"year"`
	Off        int32       `json:"off"`
	Lim        int32       `json:"lim"`
}

type ListSgkPremiumsRow struct {
	ID                  int64              `json:"id"`
	Uuid                uuid.UUID          `json:"uuid"`
	TaxpayerID          int64              `json:"taxpayer_id"`
	Period              string             `json:"period"`
	PayrollRunID        pgtype.Int8        `json:"payroll_run_id"`
	AccrualAmount       pgtype.Numeric     `json:"accrual_amount"`
	IncentiveAmount     pgtype.Numeric     `json:"incentive_amount"`
	PayableAmount       pgtype.Numeric     `json:"payable_amount"`
	DueDate             pgtype.Date        `json:"due_date"`
	DocumentNo          pgtype.Text        `json:"document_no"`
	PaidAmount          pgtype.Numeric     `json:"paid_amount"`
	PaidAt              pgtype.Date        `json:"paid_at"`
	BankTransactionID   pgtype.Int8        `json:"bank_transaction_id"`
	Note                pgtype.Text        `json:"note"`
	CreatedAt           pgtype.Timestamptz `json:"created_at"`
	UpdatedAt           pgtype.Timestamptz `json:"updated_at"`
	BankTransactionUuid pgtype.UUID        `json:"bank_transaction_uuid"`
}

func (q *Queries) ListSgkPremiums(ctx context.Context, arg ListSgkPremiumsParams) ([]ListSgkPremiumsRow, error) {
	rows, err := q.db.Query(ctx, listSgkPremiums,
		arg.TaxpayerID,
		arg.Year,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSgkPremiumsRow{}
	for rows.Next() {
		var i ListSgkPremiumsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.TaxpayerID,
			&i.Period,
			&i.PayrollRunID,
			&i.AccrualAmount,
			&i.IncentiveAmount,
			&i.PayableAmount,
			&i.DueDate,
			&i.DocumentNo,
			&i.PaidAmount,
			&i.PaidAt,
			&i.BankTransactionID,
			&i.Note,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.BankTransactionUuid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

